parameters.jsonBody:
={
  "query": "query recentSubmissions($username: String!) { recentSubmissionList(username: $username) { title titleSlug timestamp statusDisplay } }",
  "variables": {
    "username": "{{$json.username}}"
  }
}

parameters.jsCode:
const submissions = $json.data.recentSubmissionList || [];

const problemMap = {};

// Build problem map
submissions.forEach(s => {
  if (!problemMap[s.titleSlug]) {
    problemMap[s.titleSlug] = {
      title: s.title,
      titleSlug: s.titleSlug,
      attempts: 0,
      wrong: 0,
      tle: 0,
      accepted: 0,
      firstAttempt: parseInt(s.timestamp),
      lastAttempt: parseInt(s.timestamp)
    };
  }

  const p = problemMap[s.titleSlug];

  p.attempts++;

  if (s.statusDisplay === "Accepted") p.accepted++;
  if (s.statusDisplay === "Wrong Answer") p.wrong++;
  if (s.statusDisplay === "Time Limit Exceeded") p.tle++;

  const ts = parseInt(s.timestamp);
  if (ts < p.firstAttempt) p.firstAttempt = ts;
  if (ts > p.lastAttempt) p.lastAttempt = ts;
});

// Convert to array
const results = Object.values(problemMap).map(p => {

  const hadStruggle =
    p.wrong > 0 ||
    p.tle > 0 ||
    (p.attempts > 1 && p.accepted === 1);

  const base = {
    title: p.title,
    titleSlug: p.titleSlug,
    attempts: p.attempts,
    accepted: p.accepted
  };

  // ✅ Clean solve (even if re-submitted accepted multiple times)
  if (!hadStruggle) {
    return {
      json: {
        ...base,
        cleanSolve: true
      }
    };
  }

  // Calculate solve time only if struggle happened
  const timeToSolveMinutes =
    Math.floor((p.lastAttempt - p.firstAttempt) / 60);

  return {
    json: {
      ...base,
      wrong: p.wrong || undefined,
      tle: p.tle || undefined,
      struggleScore: p.attempts - p.accepted,
      timeToSolveMinutes:
        timeToSolveMinutes > 0 ? timeToSolveMinutes : undefined
    }
  };
});

return results;

// ✅ Pull original problems (with attempts & accepted)
const baseProblems = $items("FormatList").map(i => i.json);

// ✅ Pull enriched problems (with difficulty & topics)
const enrichedProblems = $items("FORMATING").map(i => i.json);

let totalAttempts = 0;
let totalAccepted = 0;

const difficultyCount = {};
const topicCount = {};

// ---- TOTALS (from FormatList) ----
baseProblems.forEach(p => {
  totalAttempts += p.attempts || 0;
  totalAccepted += p.accepted || 0;
});

// ---- Difficulty & Topics (from enriched data) ----
enrichedProblems.forEach(p => {

  if (p.difficulty) {
    difficultyCount[p.difficulty] =
      (difficultyCount[p.difficulty] || 0) + 1;
  }

  if (p.topics && Array.isArray(p.topics)) {
    p.topics.forEach(topic => {
      topicCount[topic] =
        (topicCount[topic] || 0) + 1;
    });
  }

});

// ---- Acceptance Rate ----
const acceptanceRate = totalAttempts > 0
  ? ((totalAccepted / totalAttempts) * 100)
  : 0;

let performanceLevel = "Needs Improvement";

if (acceptanceRate >= 85) performanceLevel = "Excellent";
else if (acceptanceRate >= 70) performanceLevel = "Good";
else if (acceptanceRate >= 50) performanceLevel = "Average";

const user = $item(0).$node["PickUsers"].json;


return [
  {
    json: {
      user_id: user.id,
      username: user.username,
      email: user.email,

      totalSolved: baseProblems.length,
      totalAttempts,
      totalAccepted,
      acceptanceRate: acceptanceRate.toFixed(1),
      performanceLevel,
      difficultyCount,
      topicCount
    }
  }
];

// Get analytics
const analytics = $items("RAW REPORT")?.[0]?.json ?? {};
const aiOutput = $json.cleanedAI ?? ""; // from AI CLEAN

// Safe difficulty
const difficulty = analytics.difficultyCount ?? {};
const easy = difficulty.Easy ?? 0;
const medium = difficulty.Medium ?? 0;
const hard = difficulty.Hard ?? 0;

// Safe topics
const topicCount = analytics.topicCount ?? {};

const topicBreakdown = Object.keys(topicCount).length > 0
  ? Object.entries(topicCount)
      .sort((a, b) => b[1] - a[1])
      .map(([topic, count]) => `<li><strong>${topic}</strong>: ${count}</li>`)
      .join("")
  : `<li>No topics attempted</li>`;

// 🔥 Random motivational footer
const motivationalQuotes = [
  "🚀 Small weekly improvements compound into massive growth.",
  "🔥 Consistency beats intensity. Show up every week.",
  "💡 Mastery is built one problem at a time.",
  "📈 Progress over perfection.",
  "⚡ Hard problems build strong engineers.",
  "🧠 Train your brain daily. Momentum matters.",
  "🏆 Discipline today, dominance tomorrow.",
  "🔁 Keep solving. Keep evolving.",
  "🎯 Focus. Practice. Improve. Repeat.",
  "💪 Your future self will thank you."
];

let randomQuote;

// Smart conditional footer
if ((analytics.totalSolved ?? 0) === 0) {
  randomQuote = "🌱 Every expert was once a beginner. Start this week strong.";
} else if (hard > 0) {
  randomQuote = "🔥 Solving hard problems builds elite problem solvers.";
} else {
  randomQuote =
    motivationalQuotes[
      Math.floor(Math.random() * motivationalQuotes.length)
    ];
}

// 🔹 Final formatted content
const finalReport = `
📊 Weekly LeetCode Report

Problems Solved: ${analytics.totalSolved ?? 0}

Easy: ${easy} | Medium: ${medium} | Hard: ${hard}

Topic Breakdown:
<ul>
${topicBreakdown}
</ul>

🧠 AI Revision Plan

${aiOutput}

---

${randomQuote}
`;

return [
  {
    json: {
      report: finalReport,
      footerMessage: randomQuote
    }
  }
];

let text = $items("Basic LLM Chain")[0].json.text || "";

// Convert headings properly with tight spacing
text = text.replace(/##\s*(.*)/g, `
<h3 style="
  margin:16px 0 8px 0;
  font-size:16px;
  color:#111827;
  font-weight:600;
">
$1
</h3>
`);

// Convert bullet points
text = text.replace(/\n•\s*(.*)/g, '<li style="margin-bottom:6px;">$1</li>');

// Wrap bullet groups properly
text = text.replace(/(<li.*?<\/li>)/gs, `
<ul style="
  margin:0 0 14px 18px;
  padding:0;
">
$1
</ul>
`);

// Remove unnecessary line breaks
text = text.replace(/\n{2,}/g, "");

return [{ json: { cleanedAI: text } }];

